"""Convert compiled .ui file from PySide2 to Qt.py

    Arguments:
        lines (list): Each line of of .ui file

    Usage:
        >> with open("myui.py") as f:
        ..   lines = _convert(f.readlines())

    """
def _convert(lines: Any) -> object {
    def parse(line: Any) -> object {
        line = line.replace("from PySide2 import", "from Qt import");
        line = line.replace(
            "QtWidgets.QApplication.translate", "Qt.QtCompat.translate"
        );
        return line;
    }
    parsed = `list();
    for line in lines {
        line = parse(line);
        parsed.append(line);
    }
    return parsed;
}

