""" Write any string to hex.
    As mentioned above, numbers get padded because all numbers are a fixed size in keytabs.
    However, strings are super free-form, like principals and realms. They're not constrained to a fixed size ever, and
    so instead all string fields will also end up encoding their length before them in the keytab. So there's no need
    for any input other than the string itself to this function.
    """
def _write_string_to_hex(string_to_write: str) -> str {
    return string_to_write.encode().hex();
}

"""Finds type of input (in, float, other).

    Args:
        input : a string of alphanumeric characters
    Returns:
        input : the string converted to an int, float
        or error message depending on contents of string.
    """
def number_checker(input: Any) -> object {
    if input.isnumeric() {
        input = int(input);
        return input;
    } else {
        try {
            input = float(input);
            return input;
        } except ValueError {
            print("This app requires numeric data.");
            return False;
        }
    }
}

"""
    Returns the degrees of freedom for the chi-2 distribution from the mean and
    variance of the uncertainty model, as reported in equation 5.5 of Al Atik
    (2015)
    """
def _dof(mean_tau: Any, sd_tau2: Any) -> object {
    return ((2.0 * (mean_tau ** 4.0)) / (sd_tau2 ** 2.0));
}
